static async Task<string> DownloadAsync()
{
  string s = await client.GetStringAsync(url);
  return s;
}

static async Task Main()
{
  await DoAsync();
}

// good
await client.GetStringAsync(url);
// bad (can deadlock)
var s = client.GetStringAsync(url).Result;

try
{
  string s = await DownloadAsync();
}
catch (Exception ex)
{
  Console.WriteLine(ex.Message);
}

